create table lineage_edge (id bigint generated by default as identity, source_full_name varchar(512) not null, target_full_name varchar(512) not null, relation_type varchar(32) not null, source_sql varchar(4096), dialect varchar(16), expression varchar(1024), created_at timestamp(6) with time zone not null, primary key (id), constraint uk_edge_pair unique (source_full_name, target_full_name, relation_type));
create table lineage_node (id bigint generated by default as identity, full_name varchar(512) not null unique, node_type varchar(16) not null, schema_name varchar(128), table_name varchar(128), column_name varchar(128), display_name varchar(256), created_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, primary key (id), constraint uk_node_full_name unique (full_name));
create index idx_edge_source on lineage_edge (source_full_name);
create index idx_edge_target on lineage_edge (target_full_name);
create index idx_edge_relation_type on lineage_edge (relation_type);
create index idx_node_full_name on lineage_node (full_name);
create index idx_node_type on lineage_node (node_type);
